-- Synthetic data only. Real canonical helpers, constraints, RLS and conversion.
create function public.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; end$$;
create function public.expect_failure(statement text, expected text) returns void language plpgsql as $$begin begin execute statement; exception when others then if position(expected in sqlerrm)>0 then return; end if; raise; end; raise exception 'Expected refusal: %',expected; end$$;
grant execute on function public.assert_true(boolean,text), public.expect_failure(text,text) to authenticated;
insert into auth.users(id) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,6) n;
insert into recoveryos.people(id,auth_user_id,first_name,last_name) overriding system value select n,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Synthetic','Person '||n from generate_series(1,6)n;
insert into recoveryos.organizations(id,name,organization_type) overriding system value values(1000,'Synthetic Organization A','recovery_residence_operator'),(2000,'Synthetic Organization B','recovery_residence_operator');
insert into recoveryos.residences(id,organization_id,name) overriding system value values(10,1000,'Synthetic Residence A'),(20,2000,'Synthetic Residence B');
insert into recoveryos.person_classification(person_id,classification) values(1,'production'),(2,'production'),(3,'production'),(4,'production'),(5,'test_fixture');
insert into recoveryos.role_assignments(person_id,role_key,residence_id) values(1,'residence_staff',10),(2,'residence_staff',10),(3,'residence_staff',20),(4,'administrator',null),(5,'residence_staff',10),(6,'residence_staff',10);
insert into recoveryos.residence_application_intake(id,residence_id,applicant_name,consent_to_contact,status,review_notes) overriding system value values(100,10,'Synthetic Person 5',true,'contacted','Synthetic prior contact; date unknown'),(200,20,'Synthetic Example',true,'received',null);
set role authenticated;
set test.uid='00000000-0000-0000-0000-000000000001';
select recoveryos.act_housing_follow_through(100,0,'claim');
select recoveryos.act_housing_follow_through(100,1,'contact','{"kind":"connected","date_unknown":"true","evidence":"Synthetic previously completed contact"}');
select recoveryos.act_housing_follow_through(100,2,'next_action','{"text":"Verify synthetic bed evidence","due_at":"2026-11-01T12:00:00Z"}');
select public.expect_failure($q$select recoveryos.act_housing_follow_through(100,3,'propose_cover','{"person_id":"6"}')$q$,'eligible_residence_cover_required');
select recoveryos.act_housing_follow_through(100,3,'propose_cover','{"person_id":"2"}');
set test.uid='00000000-0000-0000-0000-000000000003';
select public.assert_true((select count(*)=0 from recoveryos.housing_follow_through),'other organization/residence cannot read');
select public.expect_failure($q$select recoveryos.act_housing_follow_through(100,4,'accept_cover')$q$,'not_authorized');
set test.uid='00000000-0000-0000-0000-000000000002';
select recoveryos.act_housing_follow_through(100,4,'accept_cover');
-- Call the actual canonical conversion, not a manual status update.
select public.assert_true((recoveryos.convert_application_intake(100,5,true)->>'ok')::boolean,'canonical conversion succeeds');
select public.assert_true((select converted_person_id=5 and converted_application_id is not null and review_notes='Synthetic prior contact; date unknown' from recoveryos.residence_application_intake where id=100),'canonical links and prior review notes preserved');
select public.assert_true((select owner_person_id=2 and next_action is not null from recoveryos.housing_follow_through where intake_id=100),'work survives conversion');
select public.assert_true((select count(*)=1 from recoveryos.housing_follow_through_events where intake_id=100 and action='contact'),'completed contact survives');
select public.expect_failure($q$select recoveryos.act_housing_follow_through(100,5,'close','{"evidence":"Conversion"}')$q$,'unresolved_housing_commitments');
set test.uid='00000000-0000-0000-0000-000000000006';
select public.expect_failure($q$select recoveryos.act_housing_follow_through(100,5,'claim')$q$,'not_authorized');
set test.uid='00000000-0000-0000-0000-000000000004';
reset role;
update recoveryos.role_assignments set revoked_at=now() where person_id=2;
set role authenticated;
set test.uid='00000000-0000-0000-0000-000000000002';
select public.expect_failure($q$select recoveryos.act_housing_follow_through(100,5,'complete_action','{"evidence":"Synthetic"}')$q$,'not_authorized');
reset role;
do $$ begin
if has_table_privilege('service_role','recoveryos.housing_source_references','SELECT,INSERT,UPDATE,DELETE') then raise exception 'Private source-table access expanded'; end if;
if to_regclass('recoveryos.admin_collaboration_workspaces') is not null or to_regnamespace('recoveryos_bridge_private') is not null then raise exception 'Unrelated proposal installed'; end if;
